/* Headless smoke test for NOVA BREAKER served by the AGENT HQ server. */
import { chromium } from "playwright-core";

const URL = process.env.GAME_URL ?? "http://localhost:3002/game.html";

const browser = await chromium.launch({
  executablePath: "/usr/bin/google-chrome",
  headless: true,
  args: ["--no-sandbox", "--use-gl=swiftshader"],
});
const page = await browser.newPage({ viewport: { width: 1000, height: 780 } });

const errors = [];
page.on("pageerror", (err) => errors.push(`pageerror: ${err.message}`));
page.on("console", (msg) => {
  if (msg.type() === "error") errors.push(`console: ${msg.text()}`);
});

await page.goto(URL, { waitUntil: "networkidle" });
const hasCanvas = await page.locator("canvas#game").count();
if (hasCanvas !== 1) throw new Error("canvas not found");

// menu screenshot
await page.screenshot({ path: "/tmp/opencode/game-test/menu.png" });

// start the run, launch the ball, wedge the paddle under the ball via mouse follow
await page.keyboard.press("Space"); // menu -> playing
const state0 = await page.evaluate(() => window.novaBreaker?.state);
if (state0 !== "playing") throw new Error(`expected playing after start, got ${state0}`);

await page.mouse.move(500, 700);
await page.keyboard.press("Space"); // launch
await page.waitForFunction(() => !window.novaBreaker.balls[0]?.stuck, null, { timeout: 5000 });

// play: track the lowest live ball with the pointer for a while
await page.evaluate(() => {
  window.__follow = setInterval(() => {
    const g = window.novaBreaker;
    if (!g || g.state !== "playing") return;
    const live = g.balls.filter((b) => !b.stuck);
    if (live.length) {
      const target = live.reduce((a, b) => (b.y > a.y ? b : a));
      g.paddleTargetX = target.x;
    }
  }, 100);
});

const bricksBefore = await page.evaluate(
  () => window.novaBreaker.bricks.filter((b) => b.alive).length,
);

await page.waitForFunction(
  (before) =>
    window.novaBreaker.state === "playing" &&
    (window.novaBreaker.score > 0 ||
      window.novaBreaker.bricks.filter((b) => b.alive).length < before),
  bricksBefore,
  { timeout: 20000, polling: 250 },
);

const mid = await page.evaluate(() => ({
  state: window.novaBreaker.state,
  score: window.novaBreaker.score,
  bricksLeft: window.novaBreaker.bricks.filter((b) => b.alive).length,
  balls: window.novaBreaker.balls.length,
}));
console.log("mid-run:", JSON.stringify(mid));
await page.screenshot({ path: "/tmp/opencode/game-test/playing.png" });

// pause / resume round trip
await page.keyboard.press("p");
const paused = await page.evaluate(() => window.novaBreaker.state);
await page.keyboard.press("p");
const resumed = await page.evaluate(() => window.novaBreaker.state);
if (paused !== "paused" || resumed !== "playing") {
  throw new Error(`pause cycle failed: ${paused} -> ${resumed}`);
}

let checks = {
  bricksBefore,
  ...mid,
  pausedCycle: `${paused}->${resumed}`,
  errors,
};
console.log("CHECKS", JSON.stringify(checks, null, 2));

if (errors.length) throw new Error(`script errors: ${errors.join(" | ")}`);
if (mid.state !== "playing") throw new Error("unexpected mid-run state");
if (mid.score <= 0) throw new Error("no score registered — game is not scoring");

await page.evaluate(() => clearInterval(window.__follow));
await browser.close();
console.log("SMOKE OK");

